		}
		if !store.ValidReviewVerdict(verdictFlag) {
			return axi.Failure("signal_invalid", "--verdict must be pass, changes_requested or inconclusive", false)
		}
	}
	if len(attachments) > 0 && (verb != "done" || task.Type == "change") {
